local httpserv = game:GetService("HttpService")

local _request = request or http_request or http and http.request
local new_request = newcclosure(function(http)
    --print(http.Url)
    if http.Url:find("/api/check/")
    then
	print'found whitelist endpoeeeent ^^'
	return {
    StatusMessage = "OK",
    StatusCode = 200,
    Body = httpserv:JSONEncode({
        valid = true -- UD ✅🟢✅🟢🏳️‍🌈🏳️‍🌈 
    })
    }
end
return _request (http)
end)
if request then
    request = new_request -- func replacing ong😈😈😈
end

